    if (selection.dynamic && /process(?:\.env|\[['"]env['"]\])/u.test(body.body))
      assert.fail(`NODE_ENVIRONMENT_SHELL_UNSUPPORTED: ${file}:${sourceLine(body.start)}: dynamic interpreter stdin custody`);
